  "recovered_c": "uint64_t parse_c_expression(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return VERA_ERR;\n  }\n\n  size_t d = 0;\n  uint8_t q = 0;\n  for (size_t i = 0; i < len; i++) {\n    uint8_t uVar3 = in[i];\n    if (q == 2) {\n      q = 1;\n    } else if (q == 1) {\n      if (uVar3 == '\\') {\n        q = 2;\n      } else if (uVar3 == '\"') {\n        q = 0;\n      }\n    } else if (uVar3 == '\"') {\n      q = 1;\n    } else if (((uVar3 == '(') || (uVar3 == '[')) || (uVar3 == '{')) {\n      if (d == 0x40) {\n        return i + 1;\n      }\n      if (uVar3 == '(') {\n        uVar3 = ')';\n      } else {\n        uVar3 = uVar3 + '\n      }\n      out[d] = uVar3;\n      d = d + 1;\n    } else if (((uVar3 == ')') || (uVar3 == ']')) || (uVar3 == '}')) {\n      if ((d == 0) || (uVar3 != out[d - 1])) {\n        return i + 1;\n      }\n      d = d - 1;\n    }\n  }\n\n  return len;\n}"
}
